import { useEffect } from "react";
import PluginPage from "./PluginPage";
import "@/index.css";
import PluginUpdateNotification from "./update/PluginUpdateNotification";

declare const __CZ_APP_VERSION__: string;

export default function App() {
	useEffect(() => {
		if (window.webkit?.messageHandlers?.cosmoPd101) {
			console.log(
				"[cosmo-ui] root mounted, sending webReady",
				performance.now(),
			);
			window.webkit.messageHandlers.cosmoPd101.postMessage({
				id: 0,
				method: "webReady",
				payload: { reason: "root-mounted", time: performance.now() },
			});
		}
	}, []);

	useEffect(() => {
		const isEditableTarget = (target: EventTarget | null): boolean => {
			if (!(target instanceof Element)) {
				return false;
			}
			return Boolean(
				target.closest(
					"input, textarea, [contenteditable='true'], [data-allow-selection='true']",
				),
			);
		};

		const isInsideEditableSelection = (selection: Selection): boolean => {
			const anchorNode = selection.anchorNode;
			const focusNode = selection.focusNode;
			const anchorElement =
				anchorNode instanceof Element
					? anchorNode
					: (anchorNode?.parentElement ?? null);
			const focusElement =
				focusNode instanceof Element
					? focusNode
					: (focusNode?.parentElement ?? null);
			return isEditableTarget(anchorElement) || isEditableTarget(focusElement);
		};

		const handleSelectStart = (event: Event) => {
			if (!isEditableTarget(event.target)) {
				event.preventDefault();
			}
		};

		const handleDragStart = (event: Event) => {
			if (!isEditableTarget(event.target)) {
				event.preventDefault();
			}
		};

		const handleSelectionChange = () => {
			const selection = window.getSelection();
			if (!selection || selection.isCollapsed) {
				return;
			}
			if (!isInsideEditableSelection(selection)) {
				selection.removeAllRanges();
			}
		};

		const handleKeyDown = (event: globalThis.KeyboardEvent) => {
			if (isEditableTarget(event.target)) {
				event.stopPropagation();
			}
		};

		document.addEventListener("selectstart", handleSelectStart);
		document.addEventListener("dragstart", handleDragStart);
		document.addEventListener("selectionchange", handleSelectionChange);
		document.addEventListener("keydown", handleKeyDown);

		return () => {
			document.removeEventListener("selectstart", handleSelectStart);
			document.removeEventListener("dragstart", handleDragStart);
			document.removeEventListener("selectionchange", handleSelectionChange);
			document.removeEventListener("keydown", handleKeyDown);
		};
	}, []);

	return (
		<PluginPage
			appVersion={__CZ_APP_VERSION__}
			utilityExtra={<PluginUpdateNotification />}
		/>
	);
}
